config.code:
# The customers listed so far, and whether to ask for the next page
seen = inputs['seen'] if is_list(inputs['seen']) else []
page = inputs['page'] if is_dict(inputs['page']) else {}
rows = page.get('customers') if is_list(page.get('customers')) else []
result = {'customers': seen + rows, 'more': page.get('has_more') is True and int(inputs['number']) < 50}

# Checks the watchtowr hunt, finds the IRIS customer of each watchtowr tenant and plans one case per customer:
# its assets and, per asset, only the CVEs watchtowr targeted on it
CVE = 'CVE-[0-9]{4}-[0-9]{4,7}'
SEVERITIES = {'critical': 'Critical', 'high': 'High', 'medium': 'Medium', 'low': 'Low', 'info': 'Informational',
              'informational': 'Informational'}
MAX_STEPS = 900


def text(value, limit=500):
    return ' '.join(str(value if value is not None else '').split())[:limit]


def tag(value):
    return text(value, 50).replace(',', ' ').strip()


def cve_of(value):
    value = text(value, 40).upper()
    return value if re_fullmatch(CVE, value) is not None else None


def by_name(rows, name):
    for row in rows if is_list(rows) else []:
        if is_dict(row) and str(row.get('name') or '').strip().lower() == str(name or '').strip().lower():
            return row.get('id')
    return None


payload = inputs['payload'] if is_dict(inputs['payload']) else {}
hunt = payload.get('hunt') if is_dict(payload.get('hunt')) else {}
taxonomies = inputs['taxonomies'] if is_dict(inputs['taxonomies']) else {}
known = [c for c in (inputs['customers'] if is_list(inputs['customers']) else []) if is_dict(c)]
tenant_field = text(inputs['tenant_field'], 64)
type_rules = inputs['asset_types'] if is_dict(inputs['asset_types']) else {}
everything = text(inputs['untargeted_assets'], 10) == 'hunt'

hunt_id = text(hunt.get('id'), 100)
hunt_name = text(hunt.get('name'), 150)
hunt_url = text(hunt.get('url'), 500)
if not url_parse(hunt_url) or url_parse(hunt_url)['scheme'] != 'https':
    hunt_url = ''
level = text(hunt.get('severity'), 20).lower()
hunt_tags = [tag(t) for t in (hunt.get('tags') if is_list(hunt.get('tags')) else []) if tag(t)]

reason = ''
if not hunt_id or not hunt_name:
    reason = 'The payload has no hunt id or name (hunt.id, hunt.name): is it a watchtowr hunt parsed by Tines?'
elif not is_list(payload.get('customers')) or not payload.get('customers'):
    reason = f'The hunt {hunt_name} lists no customer (customers).'

severities = taxonomies.get('severities') if is_list(taxonomies.get('severities')) else []
severity_id = by_name(severities, SEVERITIES.get(level, 'Medium')) or by_name(severities, 'Medium')
if severity_id is None and severities:
    severity_id = severities[0].get('id')
asset_types = taxonomies.get('asset_types') if is_list(taxonomies.get('asset_types')) else []
default_type = by_name(asset_types, inputs['default_asset_type'])
if default_type is None and not reason:
    reason = (f'The asset type {text(inputs["default_asset_type"], 80)} does not exist: set default_asset_type in '
              f'the Settings node to one of Settings > Asset types.')
if severity_id is None and not reason:
    reason = 'IRIS has no severity.'

# The hunt CVEs, KEV first
cves = []
invalid = []
for vulnerability in payload.get('vulnerabilities') if is_list(payload.get('vulnerabilities')) else []:
    value = cve_of(vulnerability.get('cve') if is_dict(vulnerability) else vulnerability)
    if value is None:
        invalid.append(text(vulnerability.get('cve') if is_dict(vulnerability) else vulnerability, 40))
    elif value not in [c['cve'] for c in cves]:
        cves.append({'cve': value, 'kev': is_dict(vulnerability) and vulnerability.get('kev') is True})
cves = sorted(cves, key=lambda c: (not c['kev'], c['cve']))
kev = [c['cve'] for c in cves if c['kev']]


def customer_of(entry):
    # (IRIS customer, why not): the tenant key/value first, then the exact name
    external = text(entry.get('external_id'), 200)
    name = text(entry.get('name'), 200)
    if external and tenant_field:
        tenants = [c for c in known if is_dict(c.get('customer_key_values'))
                   and text(c['customer_key_values'].get(tenant_field), 200) == external]
        if len(tenants) == 1:
            return tenants[0], ''
        if len(tenants) > 1:
            return None, f'{len(tenants)} customers have {tenant_field} = {external}'
    named = [c for c in known if text(c.get('customer_name'), 200).lower() == name.lower()] if name else []
    if len(named) == 1:
        return named[0], ''
    if len(named) > 1:
        return None, f'{len(named)} customers are named {name}'
    return None, 'no IRIS customer has this name' + (f' or {tenant_field} = {external}' if external and tenant_field else '')


def type_of_asset(asset):
    service = text(asset.get('service'), 200).lower()
    for keyword, name in type_rules.items():
        if str(keyword).lower() in service:
            found = by_name(asset_types, name)
            if found is not None:
                return found
    return default_type


cases = {}
unmatched = []
skipped = []
for entry in payload.get('customers') if is_list(payload.get('customers')) and not reason else []:
    if not is_dict(entry):
        continue
    customer, why = customer_of(entry)
    label = text(entry.get('name') or entry.get('external_id') or '?', 200)
    if customer is None:
        unmatched.append({'name': label, 'external_id': text(entry.get('external_id'), 200), 'reason': why})
        continue
    key = str(customer.get('customer_id'))
    plan = cases.get(key)
    if plan is None:
        plan = {'customer_id': customer.get('customer_id'), 'customer_id_text': key,
                'customer_name': text(customer.get('customer_name'), 200), 'assets': []}
        cases[key] = plan
    for asset in entry.get('assets') if is_list(entry.get('assets')) else []:
        if not is_dict(asset):
            continue
        ip = text(asset.get('ip'), 64)
        ip = ip if ip_info(ip) is not None else ''
        name = text(asset.get('name'), 150) or ip
        if not name:
            skipped.append(f'{plan["customer_name"]}: an asset with neither name nor IP')
            continue
        targeted = []
        for value in asset.get('cves') if is_list(asset.get('cves')) else []:
            found = cve_of(value)
            if found is None:
                invalid.append(text(value, 40))
            elif found not in targeted:
                targeted.append(found)
        if not targeted and everything:
            targeted = [c['cve'] for c in cves]
        port = text(asset.get('port'), 10)
        service = text(asset.get('service'), 150)
        version = text(asset.get('version'), 80)
        exposure = ' '.join([p for p in (service, version) if p]) or 'Service'
        where = f'{ip}:{port}' if ip and port else ip or (f'port {port}' if port else '')
        hunt_link = f'[{hunt_name}]({hunt_url})' if hunt_url else hunt_name
        details = {'ip': ip, 'port': port, 'service': service, 'version': version, 'cves': targeted}
        same = [a for a in plan['assets'] if a['asset_name'].lower() == name.lower()]
        if same:
            # Seen twice (two tenants of one customer, or a repeated row): one asset, every CVE
            for value in targeted:
                if value not in same[0]['cves']:
                    same[0]['cves'].append(value)
            continue
        plan['assets'].append({
            'asset_name': name,
            'asset_type_id': type_of_asset(asset),
            'asset_ip': ip,
            'asset_description': f'{exposure} exposed{" on " + where if where else ""}, found by the watchtowr hunt '
                                 f'{hunt_link}.',
            'asset_info': json_dumps(details),
            'asset_tags': ','.join(['watchtowr'] + hunt_tags),
            'cves': targeted,
        })

case_tags = ','.join([t for t in [tag(t) for t in text(inputs['case_tags'], 300).split(',')] + hunt_tags if t])
planned = []
for plan in sorted(cases.values(), key=lambda p: p['customer_name'].lower()):
    lines = [f'watchtowr hunt **{hunt_name}** ({hunt_id}), severity {level or "unknown"}.']
    if hunt_url:
        lines.append(f'Hunt: {hunt_url}')
    if cves:
        lines.append('Vulnerabilities: ' + ', '.join([c['cve'] + (' (CISA KEV)' if c['kev'] else '') for c in cves]))
    lines.append('')
    lines.append('| Asset | IP | Service | Targeted CVEs |')
    lines.append('|---|---|---|---|')
    for asset in plan['assets']:
        details = json_parse(asset['asset_info'])
        service = ' '.join([p for p in (details['service'], details['version']) if p]) or '-'
        cells = [asset['asset_name'], asset['asset_ip'] or '-', service, ', '.join(asset['cves']) or '-']
        lines.append('| ' + ' | '.join([c.replace('|', '/') for c in cells]) + ' |')
    case = plan.copy()
    case.update({'case_name': f'watchtowr - {hunt_name} - {plan["customer_name"]}'[:250],
                 'case_description': '\n'.join(lines), 'case_tags': case_tags, 'soc_id': hunt_id})
    planned.append(case)

if not reason and not planned:
    reason = (f'None of the {len(unmatched)} watchtowr customer(s) of hunt {hunt_name} is an IRIS customer: '
              + '; '.join([f'{u["name"]} ({u["reason"]})' for u in unmatched])
              + f'. Set the {tenant_field} key/value of the customer in Settings > Customers.')

# Each node of each pass counts towards the steps of the run
steps = 20 + 5 * len(cves) + 5 * len(inputs['responders'] if is_list(inputs['responders']) else [])
for plan in planned:
    steps += 45 + 8 * len(plan['assets']) + 5 * len(set([c for a in plan['assets'] for c in a['cves']]))
if not reason and steps > MAX_STEPS:
    reason = (f'The hunt {hunt_name} is too large for one run (about {steps} steps for {len(planned)} case(s)): '
              f'split it per customer in Tines.')

marker = f'[watchtowr:{hunt_id}]'
room_lines = [f'watchtowr hunt {hunt_id}' + (f': {hunt_url}' if hunt_url else '')]
if kev:
    room_lines.append('In the CISA KEV catalogue: ' + ', '.join(kev))
room_lines.append(marker)

result = {
    'ok': reason == '',
    'reason': reason,
    'hunt': {'id': hunt_id, 'name': hunt_name, 'url': hunt_url, 'severity': level, 'tags': hunt_tags},
    'severity_id': severity_id,
    'room': {'name': hunt_name, 'description': '\n\n'.join(room_lines), 'marker': marker},
    'cves': [{'cve': c['cve'], 'kev': c['kev'],
              'note': f'{c["cve"]}{" (CISA KEV)" if c["kev"] else ""}: watchtowr hunt {hunt_name}'
                      + (f' {hunt_url}' if hunt_url else '')} for c in cves],
    'cases': planned,
    'unmatched': unmatched,
    'skipped': skipped + [f'not a CVE: {v}' for v in sorted(set(invalid)) if v],
}

# The assets of the case listed so far, and whether to ask for the next page
seen = inputs['seen'] if is_list(inputs['seen']) else []
page = inputs['page'] if is_dict(inputs['page']) else {}
rows = [{'asset_id': a.get('asset_id'), 'asset_name': a.get('asset_name'), 'asset_type_id': a.get('asset_type_id')}
        for a in (page.get('data') if is_list(page.get('data')) else []) if is_dict(a)]
result = {'assets': seen + rows, 'more': page.get('next_page') is not None and int(inputs['number']) < 50}

# Per CVE, the assets of the case watchtowr targeted with it: the asset of the planned name and type, else the
# only one of that name
existing = [a for a in inputs['existing'] if is_dict(a)]


def asset_id(planned):
    named = [a for a in existing if str(a.get('asset_name') or '').strip().lower() == planned['asset_name'].lower()]
    typed = [a for a in named if a.get('asset_type_id') == planned['asset_type_id']]
    if len(typed) > 0:
        return typed[0]['asset_id']
    return named[0]['asset_id'] if len(named) == 1 else None


findings = {}
missing = []
for planned in inputs['case']['assets']:
    found = asset_id(planned)
    if found is None:
        if planned['cves']:
            missing.append(planned['asset_name'])
        continue
    for value in planned['cves']:
        findings.setdefault(value, [])
        if found not in findings[value]:
            findings[value].append(found)
result = {'findings': [{'cve': k, 'asset_ids': sorted(v)} for k, v in sorted(findings.items())], 'missing': missing}

# The notification
plan = inputs['plan']
lines = []
for case in inputs['done']:
    state = 'created' if case['created'] else 'updated'
    line = (f'- {case["customer"]}: case #{case["case_id"]} {state}, {case["assets_added"]} of {case["assets"]} '
            f'asset(s) added, {case["findings"]} targeted CVE finding(s)')
    if case['missing']:
        line += ' (assets not found: ' + ', '.join(case['missing']) + ')'
    lines.append(line)
for customer in plan['unmatched']:
    lines.append(f'- Not handled: {customer["name"]} ({customer["reason"]})')
for item in plan['skipped']:
    lines.append(f'- Skipped: {item}')
cves = ', '.join([c['cve'] + (' (KEV)' if c['kev'] else '') for c in plan['cves']]) or 'none'
result = {
    'title': f'watchtowr hunt {plan["hunt"]["name"]}: {len(inputs["done"])} case(s)'
             + (f', {len(plan["unmatched"])} customer(s) not handled' if plan['unmatched'] else ''),
    'body': f'Severity {plan["hunt"]["severity"] or "unknown"}. CVEs: {cves}.\n' + '\n'.join(lines),
}
